let LookbackDays = 7d;
let WindowMinutes = 60m;
let KnownGoodChild = dynamic(["svchost.exe","conhost.exe","wuauclt.exe","mscorsvw.exe","dllhost.exe","TiWorker.exe","wermgr.exe","ngen.exe","ngentask.exe","taskhostw.exe"]);
DeviceProcessEvents
| where Timestamp > ago(LookbackDays)
| where InitiatingProcessFileName =~ "svchost.exe"
// scope to the Task Scheduler svchost instance (Schedule or netsvcs svchost group)
| where InitiatingProcessCommandLine has_any ("Schedule","netsvcs")
// Sandworm drops wipers to a 4-12 char opaque name in the Windows root, PerfLogs, ProgramData, or Users\Public to blend in / avoid AV path heuristics
| where (FolderPath matches regex @"(?i)^C:\\Windows\\[^\\]+\.exe$")
     or FolderPath has_any (@"\PerfLogs\", @"\Users\Public\", @"\ProgramData\Microsoft\")
| where FileName !in~ (KnownGoodChild)
| where FileName matches regex @"^[a-zA-Z0-9_-]{3,14}\.exe$"
| summarize FirstSeen = min(Timestamp), HostCount = dcount(DeviceName), Hosts = make_set(DeviceName, 25), Hashes = make_set(SHA256, 5), SampleCmd = any(ProcessCommandLine), SampleParentCmd = any(InitiatingProcessCommandLine)
    by FileName, bin(Timestamp, WindowMinutes)
// 3+ hosts in a 60-min window is the empirical fan-out signal for GPO-pushed wiper deployment (observed in HermeticWiper / CaddyWiper / Prestige intrusions)
| where HostCount >= 3
| order by FirstSeen desc

let LookbackDays = 14d;
let WiperDrivers = dynamic(["empntdrv.sys","emp_v9.sys","emp_v8.sys","epmntdrv.sys"]);
let EaseUSLegit = dynamic(["epm.exe","easeus.exe","empartitionmanager.exe","partitionmanager.exe","easeuspartitionmaster.exe","epm-tray.exe"]);
// Image-load path: catches the load itself in any process context
let ImageLoads = DeviceImageLoadEvents
| where Timestamp > ago(LookbackDays)
| where FileName in~ (WiperDrivers)
| where InitiatingProcessFileName !in~ (EaseUSLegit)
| where InitiatingProcessFolderPath !contains @"\Program Files\EaseUS"
| where InitiatingProcessFolderPath !contains @"\Program Files (x86)\EaseUS"
| project Timestamp, DeviceName, Source="ImageLoad", InitiatingProcessFileName, InitiatingProcessFolderPath, InitiatingProcessCommandLine, DriverFile=FileName, DriverPath=FolderPath, SHA256;
// Service-install path: HermeticWiper installs the driver as a kernel service to obtain a handle
let ServiceInstalls = DeviceEvents
| where Timestamp > ago(LookbackDays)
| where ActionType == "ServiceInstalled"
| where AdditionalFields has_any (WiperDrivers) or RegistryValueData has_any (WiperDrivers) or FileName in~ (WiperDrivers)
| where InitiatingProcessFolderPath !contains @"\Program Files\EaseUS"
| where InitiatingProcessFolderPath !contains @"\Program Files (x86)\EaseUS"
| project Timestamp, DeviceName, Source="ServiceInstall", InitiatingProcessFileName, InitiatingProcessFolderPath, InitiatingProcessCommandLine, DriverFile=FileName, DriverPath=FolderPath, SHA256;
union ImageLoads, ServiceInstalls
| order by Timestamp desc
